void coach_screen_exit_destroy(coach_screen_exit_t *out) {
    if (!out || !out->screen) return;
    lv_obj_delete(out->screen);
    out->screen = NULL;
    out->body_panel = NULL;
    out->hint_panel = NULL;
    out->mode_dot = NULL;
    out->icon = NULL;
    out->mode = NULL;
    out->battery = NULL;
    out->dest = NULL;
    out->title = NULL;
    out->primary = NULL;
    out->secondary = NULL;
    out->hint = NULL;
}
